import cv2
cap = cv2.VideoCapture('videos/a.mp4')
if not cap.isOpened():
    raise RuntimeError('Cannot open input video')
def read_frame():
    ok, frame = cap.read()
    if not ok:
        cap.release()
        return None  # End of stream; do not emit a frame event.
    return frame  # One full-resolution BGR image per event.
